var i=[{title:`Wege, Arbeit zu zählen`,text:`Die einfachste Zählung ist die Zahl der Arbeitssätze. Die „Volumenlast“ multipliziert Sätze × Wiederholungen × Gewicht, drei Sätze mit zehn Wiederholungen bei 40 kg ergeben also 1.200 kg Volumenlast für diese Übung. Das hilft, wenn du dieselbe Bewegung über die Zeit vergleichst. Es funktioniert nicht übergreifend zwischen Übungen: Ein Maschinendrücken und ein Liegestütz mit Körpergewicht lassen sich nicht in dieselben Kilogramm Reiz übersetzen.`},{title:`Harte Sätze pro Muskel`,text:`Für Muskelwachstum zählen Trainer oft die harten Sätze, die jede Muskelgruppe belasten. Grundübungen zählen für mehrere Muskeln, wenn auch nicht immer gleich stark. Eine Kniebeuge trainiert stark die Knie- und Hüftstrecker, während Rudern zusätzliche Arbeit für Rücken und Arme bringt. Wenn du jeden beteiligten Muskel zählst, als hätte er denselben Reiz bekommen, fallen deine Summen zu hoch aus.`},{title:`Wie viele Sätze du machen solltest`,text:`Das ACSM-Positionspapier 2026 fand, dass höhere Wochenumfänge, darunter mindestens etwa zehn Sätze pro Muskelgruppe, die Hypertrophie steigern können. Das ist keine Einstiegsdosis für alle und garantiert keinen Fortschritt. Anfänger verbessern sich oft mit weniger Sätzen. Erfahrenere Trainierende profitieren möglicherweise von mehr, wenn Zeit, Technik und Erholung es erlauben.`},{title:`Schrittweise aufbauen`,text:`Ein neuer Trainierender könnte mit zwei Sätzen je mehrerer Muster pro Einheit beginnen, zweimal pro Woche. Nach einigen Wochen gleichmäßiger Leistung füge einem zurückliegenden Muster nur dann einen Satz hinzu, wenn Muskelkater, Schlaf und Einheitenqualität es erlauben. Von sechs auf zwanzig harte Wochensätze für einen Muskel zu springen erhöht das Ermüdungsrisiko ohne guten Grund.`},{title:`Qualität und Quantität`,text:`Sätze mit schlechter Technik, wenig Anstrengung oder starker Ermüdung erhöhen trotzdem die Summe in der Tabelle, bringen aber wenig. Gleichmäßiger, beständiger Fortschritt ist wichtiger, als den höchsten Umfang zu haben.`},{title:`TrainUp nutzen`,text:`In jedem Training hakst du deine Sätze ab und erfasst deine Wiederholungen, und der Verlauf zeigt deine durchschnittliche Anstrengung und ein Diagramm über 4 Wochen. Vergleiche ähnliche Wochen. Wenn die Anstrengung höher als erwartet ist oder deine Wiederholungen sinken, sieh dir deinen Umfang an, bevor du mehr hinzufügst.`}];var t=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Übersichtsarbeit zu Hypertrophiemechanismen`,url:`https://pubmed.ncbi.nlm.nih.gov/35389932/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};